u_int8_t *parse_mode_settings(char *mode_ix, char *brightness, char *speed)
{
    // Map the mode to the correct base mode
    mode_data mode = modes[atoi(mode_ix)];
    u_int8_t *mode_hex = mode.mode_hex;

    u_int8_t *buf = malloc(ACTION_CODE_LEN);
    if (!buf)
        return NULL;
    memcpy(buf, mode_hex, ACTION_CODE_LEN);

    int brightness_val = atoi(brightness);
    int speed_val = atoi(speed);

    if (brightness_val < 0)
        brightness_val = 0;
    if (brightness_val > 0x0F)
        brightness_val = 0x0F;
    if (speed_val < 0)
        speed_val = 0;
    if (speed_val > 0x0F)
        speed_val = 0x0F;

    // Set the brightness/speed nibble
    buf[mode.settings_ix] = ((speed_val & 0x0F) << 4) | (brightness_val & 0x0F);

    return buf;
}